typedef struct polyline {          /* the Whole */
    point_t *pts;                  /* owned part array: freed by destroy */
    size_t   n, cap;
} polyline_t;

polyline_t *polyline_create(size_t cap);         /* creates the parts */
int         polyline_add(polyline_t *pl, point_t p);
void        polyline_destroy(polyline_t *pl);    /* frees parts, then the whole */
